// Generated from the Wikimedia Commons API (action=query&prop=imageinfo&iiprop=url|size|extmetadata, plus each file
// page's wikitext for licence-review, permission and freedom-of-panorama templates).
// All images are freely licensed for commercial reuse (CC0, public domain, CC BY or CC BY-SA); see each file page
// for full terms. Scripts/check_images.sh checks that every file here has a credit and every credit a file, and
// Scripts/make_credits.sh writes Resources/CREDITS.txt from this list.

import Foundation

/// One bundled photo's credit. `id` is the file name in Resources/Images without its extension.
struct ImageCredit: Identifiable, Sendable {
    let id: String
    /// What the photo actually shows (shown on the Credits screen and in "Illustrative" tooltips).
    let subject: String
    /// The Commons file title.
    let title: String
    let author: String
    let license: String
    /// Reuse conditions: "none" when nothing applies, otherwise any of "attribution required", "share-alike",
    /// "personality rights may apply" (identifiable people), "trademarks visible" (product or company marks) and
    /// "recent architecture (limited freedom of panorama)" (a modern building in France or Italy, where the
    /// architect's copyright can cover photos of it). A CC0 or public-domain photo can still carry the last three.
    let restrictions: String
    /// The Commons file page (source and full licence terms).
    let page: String
    /// How the bundled copy differs from the Commons original: "resized", "cropped and resized" (with what was
    /// cropped away, such as a watermark) and so on. Every bundled file is at least re-encoded and stripped of metadata.
    let modified: String

    /// A ready-to-use attribution line (TASL: title, author, source, licence).
    var attribution: String { "\"\(title)\" by \(author), \(license), via Wikimedia Commons (\(page))" }

    /// The licence deed on creativecommons.org, or nil for public-domain works (the Commons page explains those).
    var licenseURL: URL? { ImageCredit.deed(license) }

    /// Maps a Commons licence short name ("CC BY-SA 4.0", "CC BY-SA 2.0 de", "CC BY-SA 3.0 igo", "CC0") to its deed.
    static func deed(_ license: String) -> URL? {
        if license == "CC0" { return URL(string: "https://creativecommons.org/publicdomain/zero/1.0/") }
        let parts = license.split(separator: " ")
        guard parts.count >= 3, parts[0] == "CC", ["BY", "BY-SA"].contains(parts[1]) else { return nil }
        let port = parts.count > 3 ? "\(parts[3].lowercased())/" : ""
        return URL(string: "https://creativecommons.org/licenses/\(parts[1].lowercased())/\(parts[2])/\(port)")
    }
}

